// Calibration targets for the threat-relative SL (Phase 2 spec), asserted as
// orderings and bands rather than exact numbers. The full table these come
// from is generated by `scripts/calibration.ts` and printed in
// research/scoring-model.md.
import { describe, it, expect } from "vitest";
import { scorePosture, type PostureInput } from "../../src/engine/posture";
import { baselineStates } from "../../src/engine/baseline";
import { SL_BAR_PRESETS, bandWord, icd203Word, progressToward, securityLevel } from "../../src/engine/threat-sl";
import { allAt, APP_SLIDERS, FAVOURABLE_SLIDERS, loadBlocks, loadModel } from "../load-data";

const blocks = loadBlocks();
const model = loadModel();

function score(over: Partial<PostureInput>) {
  return scorePosture({
    blocks,
    model,
    blockStates: allAt(blocks, "not_started"),
    year: 2026,
    sliders: { ...APP_SLIDERS, budget_millions: 1e6 },
    adversaryOc: 4,
    modelServedExternally: true,
    ...over,
  });
}

const FULL = allAt(blocks, "mature");
const FULL_FUTURE = allAt(blocks, "mature", true);

describe("calibration targets", () => {
  it("undefended: holds OC1 (SL1) but not OC2, with no AI and no serving", () => {
    // RAND: SL1 'likely thwarts' OC1. With a RAND 1 read as 0.02 the undefended
    // lab sits just under the 1-in-5 bar against OC1.
    const r = score({ year: 2024, modelServedExternally: false });
    expect(r.tiers[0].held).toBe(true);
    expect(r.tiers[1].held).toBe(false);
    expect(r.sl.level).toBe(1);
  });

  it("undefended: serving the model, or 2026's AI, drops it below SL1", () => {
    expect(score({ year: 2024, modelServedExternally: true }).sl.level).toBe(0);
    expect(score({ year: 2026, modelServedExternally: false }).sl.level).toBe(0);
  });

  it("today's 2026 baseline posture sits at SL1–2", () => {
    for (const served of [true, false]) {
      const r = score({ blockStates: baselineStates(blocks), year: 2026, modelServedExternally: served, sliders: APP_SLIDERS });
      expect(r.sl.level, `served=${served}`).toBeGreaterThanOrEqual(1);
      expect(r.sl.level, `served=${served}`).toBeLessThanOrEqual(2);
    }
  });

  it("the full catalogue, future off, reaches SL3–4 in 2026", () => {
    for (const served of [true, false]) {
      for (const sliders of [{ ...APP_SLIDERS, budget_millions: 1e6 }, FAVOURABLE_SLIDERS]) {
        const r = score({ blockStates: FULL, sliders, modelServedExternally: served });
        expect(r.sl.level, `served=${served}`).toBeGreaterThanOrEqual(3);
        expect(r.sl.level, `served=${served}`).toBeLessThanOrEqual(4);
      }
    }
  });

  it("the full catalogue, future off, never reaches SL5", () => {
    for (const year of [2024, 2026, 2028, 2030]) {
      for (const served of [true, false]) {
        for (const sliders of [{ ...APP_SLIDERS, budget_millions: 1e6 }, FAVOURABLE_SLIDERS]) {
          expect(score({ blockStates: FULL_FUTURE, sliders, year, modelServedExternally: served }).sl.level).toBeLessThan(5);
        }
      }
    }
  });

  it("with the future blocks, in a favourable world (not served, full partnership), SL5 is reachable", () => {
    const r = score({ blockStates: FULL_FUTURE, futureCapabilities: true, sliders: FAVOURABLE_SLIDERS, modelServedExternally: false });
    expect(r.sl.level).toBe(5);
    expect(r.aiInsider.held).toBe(true);
  });

  it("...but not trivially: it needs all of it, and it does not last", () => {
    const fav = { blockStates: FULL_FUTURE, futureCapabilities: true, sliders: FAVOURABLE_SLIDERS, modelServedExternally: false };
    // Serving the model breaks it.
    expect(score({ ...fav, modelServedExternally: true }).sl.level).toBeLessThan(5);
    // So does leaving out any one of the future blocks aimed at human attackers.
    for (const id of ["FUT-01", "FUT-02", "FUT-03", "FUT-04"]) {
      const r = score({ ...fav, blockStates: { ...FULL_FUTURE, [id]: "not_started" } });
      expect(r.sl.level, `without ${id}`).toBeLessThan(5);
    }
    // Trustworthy AI monitors are what keep the lab's own model held as it
    // climbs capability bands.
    const late = { ...fav, year: 2030 };
    expect(score(late).aiInsider.held).toBe(true);
    expect(score({ ...late, blockStates: { ...FULL_FUTURE, "FUT-05": "not_started" } }).aiInsider.held).toBe(false);
    // It is marginal (OC5 within a quarter of the bar), and AI lifting the
    // attackers takes it back to SL4 by 2030.
    expect(score(fav).sl.marginal).toBe(true);
    expect(score(late).sl.level).toBe(4);
  });

  it("the AI insider is reported below SL5 but only required for it", () => {
    const r = score({ blockStates: FULL, year: 2030 });
    expect(r.aiInsider.held).toBe(false);
    expect(r.sl.level).toBeGreaterThan(0);
    expect(r.sl.level).toBeLessThan(5);
  });
});

describe("the bar τ", () => {
  it("defaults to the standard preset, and a stricter bar never raises the level", () => {
    expect(APP_SLIDERS.sl_bar).toBe(SL_BAR_PRESETS.standard);
    for (const states of [baselineStates(blocks), FULL]) {
      const at = (bar: number) => score({ blockStates: states, sliders: { ...APP_SLIDERS, budget_millions: 1e6, sl_bar: bar } }).sl;
      const strict = at(SL_BAR_PRESETS.strict);
      const standard = at(SL_BAR_PRESETS.standard);
      const lenient = at(SL_BAR_PRESETS.lenient);
      expect(strict.value).toBeLessThanOrEqual(standard.value);
      expect(standard.value).toBeLessThanOrEqual(lenient.value);
      expect(lenient.bar).toBe(0.33);
    }
  });
});

describe("threat-relative SL semantics", () => {
  it("SL is the highest n with every tier up to n held; below OC1 is level 0", () => {
    expect(securityLevel({ tierP: [0.3, 0.5, 0.9, 0.9, 0.9], aiInsiderP: 0, bar: 0.2 }).level).toBe(0);
    expect(securityLevel({ tierP: [0.1, 0.15, 0.3, 0.9, 0.9], aiInsiderP: 0.5, bar: 0.2 }).level).toBe(2);
    // SL5 also needs the AI insider held.
    expect(securityLevel({ tierP: [0.01, 0.02, 0.05, 0.1, 0.15], aiInsiderP: 0.25, bar: 0.2 }).level).toBe(4);
    expect(securityLevel({ tierP: [0.01, 0.02, 0.05, 0.1, 0.15], aiInsiderP: 0.1, bar: 0.2 }).level).toBe(5);
  });

  it("names the AI insider as what blocks SL5 when it is the binding constraint", () => {
    const r = securityLevel({ tierP: [0.01, 0.02, 0.05, 0.1, 0.15], aiInsiderP: 0.25, bar: 0.2 });
    expect(r.blocking).toEqual({ tier: 5, aiInsider: true });
    expect(securityLevel({ tierP: [0.01, 0.02, 0.05, 0.1, 0.5], aiInsiderP: 0.25, bar: 0.2 }).blocking).toEqual({
      tier: 5,
      aiInsider: false,
    });
  });

  it("progress is log(p)/log(τ): 0 at certain success, 1 at the bar, monotone between", () => {
    expect(progressToward(1, 0.2)).toBe(0);
    expect(progressToward(0.2, 0.2)).toBeCloseTo(1, 12);
    expect(progressToward(0.19, 0.2)).toBe(1);
    expect(progressToward(Math.sqrt(0.2), 0.2)).toBeCloseTo(0.5, 12);
    let last = -1;
    for (let p = 1; p >= 0.2; p -= 0.01) {
      const g = progressToward(p, 0.2);
      expect(g).toBeGreaterThanOrEqual(last);
      last = g;
    }
  });

  it("flags a held tier within 25% of the bar as marginal", () => {
    expect(securityLevel({ tierP: [0.16, 0.5, 1, 1, 1], aiInsiderP: 0, bar: 0.2 }).marginal).toBe(true);
    expect(securityLevel({ tierP: [0.14, 0.5, 1, 1, 1], aiInsiderP: 0, bar: 0.2 }).marginal).toBe(false);
    expect(securityLevel({ tierP: [0.5, 0.5, 1, 1, 1], aiInsiderP: 0, bar: 0.2 }).marginal).toBe(false);
  });

  it("reports a word band, with the ICD 203 word as detail", () => {
    expect(bandWord(0.1, 0.2)).toBe("usually fails");
    expect(bandWord(0.3, 0.2)).toBe("contested");
    expect(bandWord(0.6, 0.2)).toBe("usually succeeds");
    expect([0.01, 0.1, 0.3, 0.5, 0.7, 0.9, 0.99].map(icd203Word)).toEqual([
      "almost no chance",
      "very unlikely",
      "unlikely",
      "roughly even chance",
      "likely",
      "very likely",
      "almost certain",
    ]);
  });

  it("explains what limits the level: the tier above, its easiest approach and path", () => {
    const r = score({ blockStates: baselineStates(blocks), sliders: APP_SLIDERS });
    expect(r.sl.limitedBy).not.toBeNull();
    expect(r.sl.limitedBy!.tier).toBe(r.sl.level + 1);
    const top = r.tiers[r.sl.level].easiestApproach;
    expect(r.sl.limitedBy!.approach).toBe(top);
    expect(r.sl.limitedBy!.path.length).toBeGreaterThan(0);
  });
});

describe("block relevance", () => {
  it("names, for each block, the approaches and vectors it touches at the current posture", () => {
    const r = score({ blockStates: baselineStates(blocks), sliders: APP_SLIDERS });
    for (const b of r.catalogue) {
      const rel = r.blockRelevance[b.id];
      expect(rel, b.id).toBeDefined();
      expect(rel.vectors.map((v) => v.vectorId).sort()).toEqual(b.counters.map((c) => c.vector_id).sort());
      expect(rel.approaches.length, `${b.id} touches no approach`).toBeGreaterThan(0);
      for (const v of rel.vectors) expect(v.multiplier).toBeLessThanOrEqual(1);
    }
    // A not-started block applies nothing; a deployed one applies something.
    const notStarted = r.catalogue.find((b) => r.effectiveStates[b.id] === "not_started")!;
    expect(r.blockRelevance[notStarted.id].vectors.every((v) => v.multiplier === 1)).toBe(true);
  });
});
